//! The fixture schema (`mcp-re-http-profile-conformance/v1`), the manifest that pins
//! the corpus, and the conversions between wire messages and profile messages.

use serde::Deserialize;
use serde::Serialize;

use mcp_re_http_profile::block::AudienceTuple;
use mcp_re_http_profile::HttpRequest;
use mcp_re_http_profile::HttpResponse;

pub(super) const SCHEMA: &str = "mcp-re-http-profile-conformance/v1";

/// Third-party KATs committed in this corpus but NOT generated by the writer.
/// Pinned by hash like every other file; replayed by their own harnesses
/// (`rfc9421_cross_verification_test`, `full_profile_parity_test`), not by the
/// fixture runner, because they are not `Fixture`-shaped.
pub(super) const EXTERNAL_KATS: [&str; 1] = ["external_kat.json"];

/// Credentials in artifact fixtures are base64url-no-pad (reusing the core
/// codec so the corpus needs no extra base64 dependency).
pub(super) fn credential_b64(bytes: &[u8]) -> String {
    mcp_re_core::b64url_encode(bytes)
}

pub(super) fn base64_std_decode(s: &str) -> Vec<u8> {
    mcp_re_core::b64url_decode(s).expect("fixture credential is base64url")
}

/// What a fixture freezes, and therefore which verifier path replays it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub(super) enum Kind {
    #[serde(rename = "request")]
    Request,
    #[serde(rename = "response")]
    Response,
    #[serde(rename = "artifact")]
    Artifact,
    #[serde(rename = "continuation")]
    Continuation,
    #[serde(rename = "bodyless_202")]
    Bodyless202,
    #[serde(rename = "delegated_202")]
    Delegated202,
    #[serde(rename = "admission")]
    Admission,
    #[serde(rename = "transport_request")]
    TransportRequest,
    #[serde(rename = "chain")]
    Chain,
    #[serde(rename = "rejection")]
    Rejection,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct WireMessage {
    method: Option<String>,
    target_uri: Option<String>,
    status: Option<u16>,
    headers: Vec<(String, String)>,
    body_utf8: String,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct Oracle {
    /// Exact request signature-base bytes, base64url-no-pad.
    pub(super) signature_base_b64url: String,
    /// The request `Content-Digest` header value.
    pub(super) content_digest: String,
    /// The request `Signature` header value (label + byte sequence).
    pub(super) signature_header: String,
    /// The split-form evidence handle digest value (base64url-no-pad).
    pub(super) request_evidence_digest_value: String,
}

/// A frozen artifact-binding check (MCPRE-95). The committed `binding` is the
/// oracle (its `digest_value` is frozen); the runner recomputes the thumbprint
/// from `credential_b64` and checks the verdict. The credential surface (access
/// token / cert DER / canonical RAR details) is standard-base64 here ONLY
/// because a conformance fixture must be self-contained; on the wire it rides in
/// the covered `authorization`/`dpop` header or the mTLS layer, never in
/// evidence — the binding itself carries only the digest.
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct ArtifactCheck {
    pub(super) binding: serde_json::Value,
    pub(super) credential_b64: String,
}

/// A frozen MRTR continuation check (MCPRE-97). The committed `continuation`
/// carries the three standards-derived handles; the runner re-presents the
/// three mandated inputs (base64url) and checks the verdict. `request_state`
/// stays opaque but is digest-bound.
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct ContinuationCheck {
    pub(super) continuation: serde_json::Value,
    pub(super) previous_request_base_b64: String,
    pub(super) input_required_response_base_b64: String,
    pub(super) request_state_b64: String,
}

/// A frozen retained-CHAIN reconstruction check (#416 rev 2 §9/§13, MCPRE-431).
/// Each hop freezes the complete signed request and response; the runner replays
/// them through `reconstruct_chain` and compares the label. `outcomes` classifies
/// each hop's response terminal / input_required — MCP-level semantics the
/// standards profile is deliberately not in the business of reading from a body.
///
/// `expected_label` is `complete`, or `incomplete:<hop>:<reason>` — an incomplete
/// record must name WHICH hop broke it, so the frozen expectation names it too.
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct ChainCheck {
    pub(super) hops: Vec<ChainHop>,
    pub(super) expected_label: String,
    /// The verifier's own audience tuple. Reconstruction requires it: without one, a
    /// `Complete` label asserted only the minimal proof path, so a record could be
    /// attested whole while containing requests the enforcement boundary would refuse.
    /// Frozen HERE rather than derived from the hops, because deriving the expectation
    /// from the thing under test is not a test.
    pub(super) expected_audience: AudienceTuple,
    /// Base64url credential bytes supplied for artifact bindings whose surface the
    /// retained request does not carry. Absent means none is available, which makes
    /// every present binding fail closed.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(super) artifact_material_b64: Option<String>,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct ChainHop {
    pub(super) request: WireMessage,
    pub(super) response: WireMessage,
}

/// A frozen admission check (#414 §4.3/§5, #415 §7, MCPRE-433). The assertion JWS,
/// the call's binding, and the authoritative admission snapshot are all frozen, so
/// the §7 currency verdict is a deterministic function a third party replays. A
/// `null` authoritative state models the unreachable-authority (degraded) fork.
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct AdmissionCheck {
    pub(super) assertion_jws: String,
    pub(super) binding: serde_json::Value,
    /// `[generation, status]` — the PEP's authoritative state, or absent for the
    /// unreachable-authority case.
    pub(super) authoritative_generation: Option<u64>,
    pub(super) authoritative_status: Option<String>,
    pub(super) issuer_public_key_b64url: String,
    pub(super) allow_degraded_mode: bool,
    pub(super) degraded_propagation_bound: i64,
}

/// A frozen DELEGATED bodyless-202 check (#424, owner ruling 2026-07-17). Freezes
/// the notification request and the signed 202 (credential in the covered
/// `mcp-re-delegation` header), plus the root key + scope so the delegated
/// verification is deterministic for a third party.
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct Delegated202Check {
    pub(super) request: WireMessage,
    pub(super) response: WireMessage,
    pub(super) root_public_key_b64url: String,
    pub(super) root_kid: String,
    pub(super) verifier_audience: String,
    pub(super) audience_hash: String,
    pub(super) epoch: String,
    pub(super) revoked: bool,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct Fixture {
    pub(super) schema: String,
    pub(super) name: String,
    /// `request` fixtures verify `request`; `response` fixtures verify
    /// `response` against `request` (the ;req binding source); `artifact`
    /// fixtures verify `artifact_check`; `chain` fixtures reconstruct
    /// `chain_check`.
    pub(super) kind: Kind,
    /// `verify_ok` or the exact frozen `mcp-re.*` wire code observed.
    pub(super) expected: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(super) request: Option<WireMessage>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(super) response: Option<WireMessage>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(super) oracle: Option<Oracle>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(super) artifact_check: Option<ArtifactCheck>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(super) continuation_check: Option<ContinuationCheck>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(super) chain_check: Option<ChainCheck>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(super) admission_check: Option<AdmissionCheck>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(super) delegated_202_check: Option<Delegated202Check>,
}

/// The name, kind and frozen verdict a vector states before it carries any payload.
pub(super) struct Vector<'a> {
    pub(super) name: &'a str,
    pub(super) kind: Kind,
    pub(super) expected: &'a str,
}

impl Vector<'_> {
    /// A fixture carrying no message and no check. Each vector states the one payload it
    /// freezes through struct update.
    pub(super) fn blank(&self) -> Fixture {
        Fixture {
            schema: SCHEMA.into(),
            name: self.name.into(),
            kind: self.kind,
            expected: self.expected.into(),
            request: None,
            response: None,
            oracle: None,
            artifact_check: None,
            continuation_check: None,
            chain_check: None,
            admission_check: None,
            delegated_202_check: None,
        }
    }

    /// A fixture freezing one signed request.
    pub(super) fn for_request(&self, request: &HttpRequest) -> Fixture {
        Fixture {
            request: Some(to_wire_request(request)),
            ..self.blank()
        }
    }

    /// A fixture freezing a request and the response presented as its answer.
    pub(super) fn for_exchange(&self, request: &HttpRequest, response: &HttpResponse) -> Fixture {
        Fixture {
            request: Some(to_wire_request(request)),
            response: Some(to_wire_response(response)),
            ..self.blank()
        }
    }
}

/// One manifest entry: the fixture path and the SHA-256 of its exact bytes
/// (#415 rev 2 §12.2).
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct ManifestEntry {
    pub(super) file: String,
    /// Lowercase hex SHA-256 over the fixture file's bytes.
    pub(super) sha256: String,
}

/// The committed corpus index (#415 rev 2 §12.2).
///
/// §12.2: "a tag or branch name alone is insufficient to prove that two reviewers
/// used the same corpus." A filename list is the same problem one level down — it
/// proves which files were MEANT to be there, not what was in them. So every entry
/// carries the SHA-256 of its bytes, and `corpus_digest` commits to the whole set
/// at once.
#[derive(Debug, Serialize, Deserialize)]
pub(super) struct Manifest {
    pub(super) schema: String,
    pub(super) verify_at_unix: i64,
    /// SHA-256 over the sorted `path:hash` list — one value that names this exact
    /// corpus. Two reviewers comparing this string are comparing every byte of
    /// every vector, not a tag that can be moved.
    pub(super) corpus_digest: String,
    pub(super) fixtures: Vec<ManifestEntry>,
}

/// The §12.2 corpus digest: SHA-256 over the SORTED `<path>:<sha256>\n` list.
///
/// Sorted so the digest is a property of the corpus CONTENT, not of the order the
/// writer happened to emit fixtures in — otherwise reordering the builder would
/// change the published digest while every vector stayed byte-identical, and the
/// digest would be reporting churn instead of drift.
pub(super) fn corpus_digest(entries: &[ManifestEntry]) -> String {
    let mut lines: Vec<String> = entries
        .iter()
        .map(|e| format!("{}:{}\n", e.file, e.sha256))
        .collect();
    lines.sort();
    hex_sha256(lines.concat().as_bytes())
}

pub(super) fn hex_sha256(bytes: &[u8]) -> String {
    use sha2::Digest;
    let d = sha2::Sha256::digest(bytes);
    d.iter().map(|b| format!("{b:02x}")).collect()
}

pub(super) fn to_wire_request(r: &HttpRequest) -> WireMessage {
    WireMessage {
        method: Some(r.method.clone()),
        target_uri: Some(r.target_uri.clone()),
        status: None,
        headers: r.headers.clone(),
        body_utf8: String::from_utf8(r.body.clone()).expect("test bodies are UTF-8"),
    }
}

pub(super) fn to_wire_response(r: &HttpResponse) -> WireMessage {
    WireMessage {
        method: None,
        target_uri: None,
        status: Some(r.status),
        headers: r.headers.clone(),
        body_utf8: String::from_utf8(r.body.clone()).expect("test bodies are UTF-8"),
    }
}

pub(super) fn from_wire_request(w: &WireMessage) -> HttpRequest {
    HttpRequest {
        method: w.method.clone().expect("request fixture has method"),
        target_uri: w
            .target_uri
            .clone()
            .expect("request fixture has target_uri"),
        headers: w.headers.clone(),
        body: w.body_utf8.clone().into_bytes(),
    }
}

pub(super) fn from_wire_response(w: &WireMessage) -> HttpResponse {
    HttpResponse {
        status: w.status.expect("response fixture has status"),
        headers: w.headers.clone(),
        body: w.body_utf8.clone().into_bytes(),
    }
}

/// The first existing runfile path for `rel`, trying each runfiles root Bazel may set
/// and then `rel` itself as a plain path.
fn runfile(rel: &str) -> Option<std::path::PathBuf> {
    ["TEST_SRCDIR", "RUNFILES_DIR"]
        .iter()
        .filter_map(|key| std::env::var(key).ok())
        .map(|root| std::path::Path::new(&root).join(rel))
        .chain(std::iter::once(std::path::PathBuf::from(rel)))
        .find(|candidate| candidate.exists())
}

/// Locate the committed corpus under BOTH build systems (same dual-mode
/// bridge as the draft-02 corpus; Bazel passes
/// `MCP_RE_HTTP_PROFILE_VECTORS_MANIFEST = $(rlocationpath ...)`).
pub(super) fn vectors_root() -> std::path::PathBuf {
    let Ok(rel) = std::env::var("MCP_RE_HTTP_PROFILE_VECTORS_MANIFEST") else {
        return std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests")
            .join("vectors")
            .join("http-profile");
    };
    let manifest = runfile(&rel).unwrap_or_else(|| {
        panic!("MCP_RE_HTTP_PROFILE_VECTORS_MANIFEST set but runfile not found (rel={rel})")
    });
    manifest
        .parent()
        .expect("manifest has a parent")
        .to_path_buf()
}
